const $=s=>document.querySelector(s),escape=Vibe.escape;
const IDE={projects:[],id:'',file:'',hash:'',saved:'',editor:null,job:null,cursor:0,events:[],timer:null,loading:false,dark:localStorage.getItem('vibe-practice-theme')==='dark'};
function notice(text,error=false){$('#notice').textContent=text;$('#notice').classList.toggle('error',error);}
const api=(p,b)=>Vibe.api(p,b), endpoint=s=>'/projects/'+IDE.id+s;
function value(){return IDE.editor?IDE.editor.getValue():$('#fallback').value;}
function dirty(){return !!IDE.file&&value()!==IDE.saved;}
function mark(){if(!IDE.loading)$('#dirty').textContent=dirty()?'Unsaved':'';}
function setValue(text,file){IDE.loading=true;if(IDE.editor){IDE.editor.setValue(text);monaco.editor.setModelLanguage(IDE.editor.getModel(),({js:'javascript',mjs:'javascript',json:'json',html:'html',css:'css',md:'markdown',ts:'typescript',tsx:'typescript',py:'python'})[file.split('.').pop()]||'plaintext');}else $('#fallback').value=text;IDE.saved=text;IDE.loading=false;mark();}
async function loadProjects(){IDE.projects=(await api('/projects')).projects;$('#projects').innerHTML=IDE.projects.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('')||'<option value="">Create your first project</option>';const requested=new URLSearchParams(location.search).get('project');await selectProject(IDE.projects.some(p=>p.id===requested)?requested:IDE.projects[0]?.id||'');}
async function selectProject(id){if(dirty()&&!confirm('Discard unsaved changes?')){$('#projects').value=IDE.id;return;}clearInterval(IDE.timer);IDE.id=id;IDE.file='';IDE.hash='';IDE.events=[];IDE.cursor=0;IDE.job=null;setValue('','');$('#filename').textContent='Select a file';$('#activity').textContent='';$('#projects').value=id;controls();if(!id){notice('Create a project to begin.');return;}const p=IDE.projects.find(p=>p.id===id);$('#edition').textContent=p.edition==='law'?'Vibe Law':'Vibe One';history.replaceState(null,'','?project='+encodeURIComponent(id));await files();await historyRuns();await preview();notice('Project ready. Edit a file or describe your next change.');if(p.activeJob)watch(p.activeJob);}
async function files(){if(!IDE.id)return;const result=await api(endpoint('/files'));$('#tree').innerHTML=result.files.map(f=>`<button data-file="${escape(f.path)}" title="${escape(f.path)}">${escape(f.path)}</button>`).join('');$('#tree').querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>openFile(b.dataset.file).catch(e=>notice(e.message,true)));if(!IDE.file&&result.files.length){const first=result.files.find(f=>f.path==='index.html')||result.files.find(f=>/\.(tsx?|jsx?)$/.test(f.path))||result.files[0];await openFile(first.path);}else if(IDE.file&&!result.files.some(f=>f.path===IDE.file)){IDE.file='';setValue('','');$('#filename').textContent='Select a file';}}
async function openFile(path){if(dirty()&&!confirm('Discard unsaved changes?'))return;const result=await api(endpoint('/files?path='+encodeURIComponent(path)));IDE.file=path;IDE.hash=result.hash;setValue(result.text,path);$('#filename').textContent=path;$('#tree').querySelectorAll('[data-file]').forEach(b=>b.classList.toggle('selected',b.dataset.file===path));}
async function save(){if(!IDE.file)return;const result=await api(endpoint('/file'),{path:IDE.file,text:value(),hash:IDE.hash});IDE.hash=result.hash;IDE.saved=value();mark();notice('Saved '+IDE.file);await preview();}
async function preview(){if(!IDE.id)return;const info=await api(endpoint('/preview'));$('#preview').hidden=!info.available;$('#preview-empty').hidden=!!info.available;$('#open-preview').hidden=!info.available;if(info.available){$('#preview').src=info.url;$('#open-preview').href=info.url;}else $('#preview-empty').textContent=info.message;}
function controls(){const running=IDE.job&&['running','queued','cancelling'].includes(IDE.job.status);for(const id of ['build','install','verify','save','delete','new-file','starter'])$('#'+id).disabled=!IDE.id||!!running;$('#stop').disabled=!running||IDE.job.status==='cancelling';}
async function historyRuns(){if(!IDE.id)return;const r=await api(endpoint('/jobs'));$('#history').innerHTML='<option value="">Select a run…</option>'+r.jobs.slice().reverse().map(j=>`<option value="${escape(j.id)}">${escape(j.kind)} · ${escape(j.status)} · ${escape(new Date(j.createdAt).toLocaleTimeString())}</option>`).join('');}
function activity(){const opened=new Set([...$('#activity').querySelectorAll('details[open]')].map(e=>e.dataset.seq));$('#activity').innerHTML=IDE.events.map(e=>`<details data-seq="${e.seq}" ${['assistant','error','status'].includes(e.kind)||opened.has(String(e.seq))?'open':''}><summary>${escape(e.kind)} · ${escape(new Date(e.time).toLocaleTimeString())}</summary><pre>${escape(e.text)}</pre></details>`).join('');}
function watch(id){clearInterval(IDE.timer);IDE.cursor=0;IDE.events=[];const project=IDE.id;let busy=false;const poll=async()=>{if(busy||IDE.id!==project)return;busy=true;try{const j=await api('/jobs/'+id+'?after='+IDE.cursor);IDE.job=j;for(const e of j.events){IDE.events.push(e);IDE.cursor=Math.max(IDE.cursor,e.seq);}activity();controls();notice(j.kind+' · '+j.status,j.status==='failed'||j.status==='needs_attention');if(!['running','queued','cancelling'].includes(j.status)){clearInterval(IDE.timer);await files();if(IDE.file&&!dirty())await openFile(IDE.file);await historyRuns();await preview();}}catch(e){clearInterval(IDE.timer);notice('Connection interrupted. Select the run in history to reconnect. '+e.message,true);}finally{busy=false;}};poll();IDE.timer=setInterval(poll,1600);}
async function action(kind){try{if(dirty())await save();if(kind==='build'&&!$('#task').value.trim())throw Error('Describe the next change first.');const j=await api(endpoint('/'+kind),kind==='build'?{provider:'codex',task:$('#task').value}:{});watch(j.id);}catch(e){notice(e.message,true);}}
function theme(){document.body.classList.toggle('dark',IDE.dark);if(IDE.editor)monaco.editor.setTheme(IDE.dark?'vs-dark':'vs');localStorage.setItem('vibe-practice-theme',String(IDE.dark?'dark':'light'));}
$('#projects').onchange=()=>selectProject($('#projects').value).catch(e=>notice(e.message,true));$('#save').onclick=()=>save().catch(e=>notice(e.message,true));$('#fallback').oninput=mark;$('#theme').onclick=()=>{IDE.dark=!IDE.dark;theme();};theme();
for(const kind of ['build','install','verify'])$('#'+kind).onclick=()=>action(kind);
$('#history').onchange=()=>{if($('#history').value)watch($('#history').value);};$('#stop').onclick=async()=>{try{if(IDE.job)await api('/jobs/'+IDE.job.id+'/cancel',{});}catch(e){notice(e.message,true);}};
$('#refresh').onclick=()=>preview().catch(e=>notice(e.message,true));$('#new-file').onclick=async()=>{const path=prompt('New file path, for example src/app.js');if(!path)return;try{if(dirty())await save();await api(endpoint('/file'),{path,text:''});await files();await openFile(path);}catch(e){notice(e.message,true);}};
$('#delete').onclick=async()=>{if(!IDE.file||!confirm('Delete '+IDE.file+'? A recovery copy is retained locally.'))return;try{await api(endpoint('/file'),{path:IDE.file,hash:IDE.hash,remove:true});IDE.file='';setValue('','');await files();await preview();}catch(e){notice(e.message,true);}};
$('#starter').onclick=async()=>{try{const p=IDE.projects.find(p=>p.id===IDE.id);await api(endpoint('/template'),{template:p.edition==='law'?'legal':'web'});await files();await preview();notice('Starter added. Edit the source or ask Codex to extend it.');}catch(e){notice(e.message,true);}};
$('#diff').onclick=async()=>{try{const d=await api(endpoint('/diff'));$('#patch').textContent=(d.summary||'No tracked changes.')+'\n\nNew files:\n'+d.untracked.join('\n')+'\n\n'+d.patch;$('#diff-dialog').showModal();}catch(e){notice(e.message,true);}};$('#close-diff').onclick=()=>$('#diff-dialog').close();
$('#new-project').onclick=()=>{$('#create-error').textContent='';$('#create-form [name=edition]').value=Vibe.user.defaultEdition;$('#new-dialog').showModal();};$('#close-dialog').onclick=()=>$('#new-dialog').close();
$('#create-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('.primary');button.disabled=true;try{const input=Object.fromEntries(new FormData(event.target));const p=await api('/projects',{brief:{...input,features:input.goal}});if(input.template!=='blank')await api('/projects/'+p.id+'/template',{template:input.template});IDE.projects=(await api('/projects')).projects;$('#projects').innerHTML=IDE.projects.map(p=>`<option value="${escape(p.id)}">${escape(p.name)}</option>`).join('');$('#new-dialog').close();await selectProject(p.id);}catch(e){$('#create-error').textContent=e.message;}finally{button.disabled=false;}};
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();save().catch(e=>notice(e.message,true));}});addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
for(const b of document.querySelectorAll('[data-view]'))if(b.tagName==='BUTTON')b.onclick=()=>{document.querySelector('.ide').dataset.view=b.dataset.view;document.querySelectorAll('button[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));IDE.editor?.layout();};
const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(Speech){$('#voice').hidden=false;let speech;$('#voice').onclick=()=>{if(speech){speech.stop();return;}speech=new Speech();speech.lang=navigator.language;speech.onresult=e=>{$('#task').value+=( $('#task').value?' ':'')+e.results[0][0].transcript;};speech.onerror=e=>notice('Dictation: '+e.error,true);speech.onend=()=>{speech=null;$('#voice').textContent='Dictate';};speech.start();$('#voice').textContent='Stop dictation';};}
(async()=>{try{await Vibe.require();$('#account').textContent=Vibe.user.name;await loadProjects();if(window.require){require.config({paths:{vs:location.origin+'/vendor/monaco/vs'}});require(['vs/editor/editor.main'],()=>{const text=$('#fallback').value;$('#fallback').hidden=true;IDE.editor=monaco.editor.create($('#editor'),{value:text,language:'html',theme:IDE.dark?'vs-dark':'vs',automaticLayout:true,minimap:{enabled:false},fontSize:13,scrollBeyondLastLine:false});IDE.editor.onDidChangeModelContent(mark);setValue(text,IDE.file);},()=>notice('Advanced editor unavailable; the text editor remains usable.'));}const status=await api('/status');$('#agent-status').textContent=status.providers.codex.signedIn?'Signed in · ChatGPT subscription':'Run codex login on this computer';}catch(e){notice(e.message,true);}})();

